q(9,2,'Mechanical efficiency','Indicated power is 500 kW and brake power is 450 kW. Find mechanical efficiency as a fraction.',.9,'','Brake power is the useful shaft output in this ratio.', ['ηm = Pb/Pi','ηm = 450/500'],S('book-c9-p136-r06',{P_b:450,P_i:500}));
