q(9,4,'Brake thermal efficiency','Brake power is 400 kW, fuel flow 0.02 kg/s and LHV=40000 kJ/kg. Find brake thermal efficiency.',.5,'','Fuel power and shaft power must use the same energy/time units.', ['Pfuel = 0.02×40000 = 800 kW','ηb = 400/800'],S('book-c9-p136-r02',{P_b:400,'ṁ_f':.02,LHV:40000}));
