q(9,9,'Ideal Otto cycle','For a calorically perfect ideal Otto cycle with compression ratio 8 and κ=1.4, find thermal efficiency as a fraction.',1-8**(-.4),'','Use the ideal air-standard expression; this is not measured brake efficiency.', ['η = 1−r^(1−κ)','η = 1−8^(−0.4)'],S('book-c9-p134-r04',{r:8,'κ':1.4}));
q(9,10,'Polytropic compression temperature','A gas starts at 300 K and is compressed at volume ratio 10 with polytropic exponent 1.3. Find final temperature.',300*10**.3,'K','Use absolute temperature and exponent np−1.', ['T₂ = T₁ r^(np−1)','T₂ = 300×10^0.3'],S('book-c9-p135-r05',{'T₁':300,r:10,n_p:1.3}));
q(9,11,'Combustion air','Fuel flow is 0.01 kg/s, stoichiometric air–fuel mass ratio 14.5 and excess-air ratio 1.6. Find supplied air mass flow.',.232,'kg/s','Excess-air ratio multiplies the stoichiometric air requirement.', ['ṁair = ṁf λ AFRst','ṁair = 0.01×1.6×14.5'],S('book-c9-p139-r02',{'ṁ_f':.01,'λ':1.6,AFR_st:14.5}));
q(9,12,'Scavenging balance','A two-stroke cylinder receives 0.12 kg fresh air per cycle and short-circuits 0.03 kg. Reference air mass is 0.10 kg. Find charging efficiency.',.9,'','Subtract short-circuited fresh air before dividing by reference mass.', ['mret = 0.12−0.03 = 0.09 kg','ηcharge = mret/mref = 0.09/0.10'],[S('book-c9-p141-r05',{m_ret:.09,m_short:.03},{expected:.12}),S('book-c9-p141-r03',{m_ret:.09,m_ref:.1})]);
q(9,13,'Ideal Diesel cycle','For an ideal Diesel cycle with κ=1.4, compression ratio 16 and cutoff ratio 2, find thermal efficiency as a fraction.',1-(2**1.4-1)/(1.4*16**.4),'','The cutoff correction divides the Otto-like compression term.', ['η = 1−(rc^κ−1)/[κ(rc−1)r^(κ−1)]','η = 1−(2^1.4−1)/(1.4×1×16^0.4)'],S('book-c9-p135-r01',{r_c:2,'κ':1.4,r:16}));
