q(9,15,'Second-order crank acceleration','Use the second-order crank approximation at θ=90° for R=0.10 m, rod length L=0.40 m and ω=100 rad/s. Find signed piston acceleration, positive away from TDC.',-250,'m/s²','At 90°, the primary cosine vanishes and cos(2θ)=−1.', ['λr = R/L = 0.25','a ≈ Rω²(cosθ+λr cos2θ) = 0.1×10000×(0−0.25)'],S('book-c9-p142-r04',{R:.1,'ω':100,'θ':pi/2,'λ_r':.25}));
