q(10,1,'Steam quality','At a specified saturation pressure, hf=500 kJ/kg and hfg=2000 kJ/kg. Find mixture enthalpy for quality x=0.9.',2300,'kJ/kg','Quality is the vapour mass fraction; both properties refer to the same pressure.', ['h = hf+x hfg','h = 500+0.9×2000'],S('book-c10-p149-r02',{h_f:500,x:.9,h_fg:2000}));
q(10,2,'Density from specific volume','A steam state has specific volume 0.2 m³/kg. Find density.',5,'kg/m³','Density and specific volume are reciprocal properties.', ['ρ = 1/v','ρ = 1/0.2'],S('book-c10-p149-r05',{v:.2}));
q(10,3,'Mechanical turbine efficiency','A turbine has indicated power 1000 kW and shaft power 950 kW. Find mechanical efficiency.',.95,'','This ratio covers mechanical transmission, not isentropic efficiency.', ['ηm = Psh/Pi','ηm = 950/1000'],S('book-c10-p149-r07',{P_sh:950,P_i:1000}));
