q(10,5,'Wetness fraction','At a supplied saturation state hg=2800 kJ/kg and hfg=2000 kJ/kg. Wetness fraction is 0.10. Find mixture enthalpy.',2600,'kJ/kg','Wetness is liquid mass fraction, so subtract its latent-heat contribution.', ['h = hg−fwet hfg','h = 2800−0.10×2000'],S('book-c10-p149-r01',{h_g:2800,f_wet:.1,h_fg:2000}));
q(10,6,'Mixture specific volume','At one saturation pressure vf=0.001 m³/kg and vg=0.5 m³/kg. For quality x=0.8, find mixture specific volume.',.4002,'m³/kg','Mass-weight the liquid and vapour specific volumes.', ['v = (1−x)vf+xvg','v = 0.2×0.001+0.8×0.5'],S('book-c10-p149-r06',{x:.8,v_f:.001,v_g:.5}));
