q(10,12,'Conduction resistance','A plane wall has k=0.5 W/(m·K), area 10 m², thickness 0.1 m and temperature difference 30 K. Find heat rate.',1500,'W','Conduction rate is proportional to area and inverse thickness.', ['Q̇ = kAΔT/δ','Q̇ = 0.5×10×30/0.1'],S('book-c10-p154-r01',{k:.5,A:10,'ΔT':30,'δ':.1}));
