q(10,16,'Simple turbine–boiler balance','A simplified cycle has h₁=3200, h₂=2400 and condensate hcond=200 kJ/kg, neglecting pump work and losses. Find the approximate cycle efficiency.',4/15,'','Divide turbine work per unit mass by the supplied heat per unit mass.', ['wt = 3200−2400 = 800 kJ/kg','qin = 3200−200 = 3000 kJ/kg; η≈800/3000'],S('book-c10-p151-r02',{'h₁':3200,'h₂':2400,h_cond:200}));
