q(12,2,'Refrigeration COP','Given h₁=400, h₂=450 and h₄=250 kJ/kg, find the idealized refrigerant-side cooling COP.',3,'','Cooling effect and compressor enthalpy rise share the same mass-flow factor.', ['COP = (h₁−h₄)/(h₂−h₁)','COP = 150/50'],S('book-c12-p177-r03',{'h₁':400,'h₂':450,'h₄':250}));
